\SemioTableLong[text-size=8pt]{\Key{api-path-network-force} \ApiText{Force layout options}{Optionen des Kräftelayouts}}{0.19,0.12,0.16,0.53}{\ApiKey & \ApiType & \ApiDefault & \ApiMeaning}{%
  \SemioTableRow{\Key{iterations} & \Key{integer} & \Key{300} & \ApiText{Simulation ticks; cost grows with ticks times nodes squared plus edges.}{Simulationstakte; der Aufwand wächst mit Takten mal Knoten zum Quadrat plus Kanten.}}
  \SemioTableRow{\Key{alpha} & \Key{number} & \Key{1} & \ApiText{Initial simulation temperature.}{Anfängliche Simulationstemperatur.}}
  \SemioTableRow{\Key{alpha-min} & \Key{number} & \Key{0.001} & \ApiText{Minimum temperature used to derive automatic decay.}{Mindesttemperatur zur Herleitung des automatischen Abfalls.}}
  \SemioTableRow{\Key{alpha-decay} & \Key{number} & \Key{-1} & \ApiText{Negative means automatic decay: one minus alpha-min to the power of one over 300.}{Negativ bedeutet automatischer Abfall: eins minus alpha-min hoch eins durch 300.}}
  \SemioTableRow{\Key{alpha-target} & \Key{number} & \Key{0} & \ApiText{Target temperature approached on each tick.}{Zieltemperatur, die bei jedem Takt angenähert wird.}}
  \SemioTableRow{\Key{velocity-decay} & \Key{number} & \Key{0.4} & \ApiText{Public damping fraction; velocity is multiplied by one minus this value.}{Öffentlicher Dämpfungsanteil; die Geschwindigkeit wird mit eins minus diesem Wert multipliziert.}}
  \SemioTableRow{\Key{forces} & \Key{list} & \Key{link}, \Key{many-body}, \Key{center} & \ApiText{Force names in application order: link, many-body, center, collide, x, y or radial.}{Kraftnamen in Anwendungsreihenfolge: link, many-body, center, collide, x, y oder radial.}}
  \SemioTableRow{\Key{link-distance} & \Key{number} & \Key{30} & \ApiText{Link rest length in layout units.}{Ruhelänge der Kanten in Layouteinheiten.}}
  \SemioTableRow{\Key{link-strength} & \Key{number} & \Key{-1} & \ApiText{Negative selects one divided by the smaller endpoint degree.}{Negativ wählt eins geteilt durch den kleineren Endknotengrad.}}
  \SemioTableRow{\Key{link-iterations} & \Key{integer} & \Key{1} & \ApiText{Link force passes per tick.}{Durchläufe der Kantenkraft je Takt.}}
  \SemioTableRow{\Key{many-body-strength} & \Key{number} & \Key{-30} & \ApiText{Charge of every node; negative values repel.}{Ladung jedes Knotens; negative Werte stoßen ab.}}
  \SemioTableRow{\Key{distance-min} & \Key{number} & \Key{1} & \ApiText{Minimum distance clamp for the many-body force in layout units.}{Untere Abstandsbegrenzung der Vielkörperkraft in Layouteinheiten.}}
  \SemioTableRow{\Key{distance-max} & \Key{number} & \Key{-1} & \ApiText{Maximum many-body distance; negative means no upper cutoff.}{Maximaler Vielkörperabstand; negativ bedeutet keine obere Grenze.}}
  \SemioTableRow{\Key{center-x} & \Key{number} & \Key{0} & \ApiText{Horizontal centroid target.}{Waagerechtes Schwerpunktziel.}}
  \SemioTableRow{\Key{center-y} & \Key{number} & \Key{0} & \ApiText{Vertical centroid target.}{Senkrechtes Schwerpunktziel.}}
  \SemioTableRow{\Key{center-strength} & \Key{number} & \Key{1} & \ApiText{Fraction of centroid displacement applied on each tick.}{Anteil der Schwerpunktverschiebung je Takt.}}
  \SemioTableRow{\Key{collide-radius} & \Key{number} & \Key{1} & \ApiText{Uniform collision radius in layout units.}{Einheitlicher Kollisionsradius in Layouteinheiten.}}
  \SemioTableRow{\Key{collide-strength} & \Key{number} & \Key{0.7} & \ApiText{Collision resolution strength.}{Stärke der Kollisionsauflösung.}}
  \SemioTableRow{\Key{collide-iterations} & \Key{integer} & \Key{1} & \ApiText{Collision force passes per tick.}{Durchläufe der Kollisionskraft je Takt.}}
  \SemioTableRow{\Key{x-target} & \Key{number} & \Key{0} & \ApiText{Target coordinate of the horizontal spring.}{Zielkoordinate der waagerechten Feder.}}
  \SemioTableRow{\Key{x-strength} & \Key{number} & \Key{0.1} & \ApiText{Horizontal spring strength.}{Stärke der waagerechten Feder.}}
  \SemioTableRow{\Key{y-target} & \Key{number} & \Key{0} & \ApiText{Target coordinate of the vertical spring.}{Zielkoordinate der senkrechten Feder.}}
  \SemioTableRow{\Key{y-strength} & \Key{number} & \Key{0.1} & \ApiText{Vertical spring strength.}{Stärke der senkrechten Feder.}}
  \SemioTableRow{\Key{radial-radius} & \Key{number} & \Key{100} & \ApiText{Target radius of the radial spring in layout units.}{Zielradius der radialen Feder in Layouteinheiten.}}
  \SemioTableRow{\Key{radial-x} & \Key{number} & \Key{0} & \ApiText{Horizontal centre of the radial spring.}{Waagerechter Mittelpunkt der radialen Feder.}}
  \SemioTableRow{\Key{radial-y} & \Key{number} & \Key{0} & \ApiText{Vertical centre of the radial spring.}{Senkrechter Mittelpunkt der radialen Feder.}}
  \SemioTableRow{\Key{radial-strength} & \Key{number} & \Key{0.1} & \ApiText{Radial spring strength.}{Stärke der radialen Feder.}}
  \SemioTableRow{\Key{seed} & \Key{number} & \Key{1} & \ApiText{Seed of the deterministic linear congruential generator used by the force simulation.}{Startwert des deterministischen linearen Kongruenzgenerators der Kräftesimulation.}}
}

